 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mix, smoothstep, color, vec3, fract, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh } = THREE;

  const group = new Group();

  // Stage: engineered gradient surface with subtle grain
  const bgGeo = new PlaneGeometry(7, 6);
  const u = uv();

  const cInk = color('#16161d');
  const cSurface = color('#0b0b10');
  const gradT = smoothstep(0.25, 0.75, u.y);
  const grad = mix(cSurface, cInk, gradT);

  const grainHash = fract(sin(u.x.mul(12.9898).add(u.y.mul(78.233))).mul(43758.5453));
  const grainMix = mix(grad, grad.mul(vec3(1.06)), grainHash.mul(0.08));

  const bgMat = new MeshBasicNodeMaterial({ colorNode: grainMix });
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.z = -2.5;
  group.add(bg);

  // Textured card plane (512 x 320 source rect)
  const cardWidth = 0.5;
  const cardHeight = cardWidth * (320 / 512);
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshBasicNodeMaterial({
    colorNode: color('#0b0b10'),
    transparent: true
  });
  cardMat.alphaTest = 0.05;

  const card = new Mesh(cardGeo, cardMat);
  card.position.z = 0;
  group.add(card);

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      cardMat.colorNode = texture(tex, uv());
      cardMat.needsUpdate = true;
    });
  }

  // Accent indicator
  const accentGeo = new PlaneGeometry(0.18, 0.012);
  const accentMat = new MeshBasicNodeMaterial({ colorNode: color('#ff2a38') });
  const accent = new Mesh(accentGeo, accentMat);
  accent.position.set(-cardWidth * 0.5 + 0.09, -cardHeight * 0.5 - 0.06, 0.011);
  group.add(accent);

  // Text label
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const text = String(item.text ?? '');
    if (!text) continue;

    const fontSize = item.typography?.fontSize ?? 39;
    const textObj = ctx.fontAtlas.createText(text, {
      fontSize,
      color: '#e8ecf2',
      align: 'left'
    });

    textObj.position.set(-cardWidth * 0.5, -cardHeight * 0.5 - 0.1, 0.011);
    group.add(textObj);
  }

  // No interactions configured
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    bgGeo.dispose();
    bgMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
  };

  return group;
}
